  ev jsonb; pa jsonb; eid uuid; pid uuid; ord int; ml text; mv text;
begin
  for ev in select value from jsonb_array_elements(spec->'events') loop
    insert into events(name, type, description)
      values(ev->>'name', nullif(ev->>'type',''), nullif(ev->>'description',''))
      on conflict(name) do update set type=excluded.type, description=excluded.description, is_active=true
      returning id into eid;
    ord := 0;
    for pa in select value from jsonb_array_elements(ev->'params') loop
      insert into parameters(name, value_type, formatting, fallback_value, is_mapped, definition, example)
        values(pa->>'name', nullif(pa->>'value_type',''), nullif(pa->>'formatting',''), nullif(pa->>'fallback',''),
               jsonb_array_length(coalesce(pa->'mapped','[]'::jsonb)) > 0,
               nullif(pa->>'definition',''), nullif(pa->>'example',''))
        on conflict(name) do update set
          value_type     = coalesce(parameters.value_type, excluded.value_type),
          formatting     = coalesce(parameters.formatting, excluded.formatting),
          fallback_value = coalesce(parameters.fallback_value, excluded.fallback_value),
          is_mapped      = parameters.is_mapped or excluded.is_mapped,
          definition     = coalesce(parameters.definition, excluded.definition),
          example        = coalesce(parameters.example, excluded.example),
          is_active      = true
        returning id into pid;
      ml := (select string_agg(x, '|') from jsonb_array_elements_text(coalesce(pa->'mapped','[]'::jsonb)) x);
      insert into event_parameters(event_id, parameter_id, required, example, value_type, formatting, fallback, mapped_list_raw, display_order, change_status)
        values(eid, pid, nullif(pa->>'required',''), nullif(pa->>'example',''), nullif(pa->>'value_type',''),
               nullif(pa->>'formatting',''), nullif(pa->>'fallback',''), ml, ord,
               case when upper(coalesce(pa->>'change',''))='NEW' then 'NEW'
                    when coalesce(pa->>'change','') <> '' then 'UPDATED' else null end)
        on conflict(event_id, parameter_id) do update set
          required=excluded.required, example=excluded.example, value_type=excluded.value_type,
          formatting=excluded.formatting, fallback=excluded.fallback, mapped_list_raw=excluded.mapped_list_raw,
          display_order=excluded.display_order, change_status=excluded.change_status, is_active=true;
      for mv in select value from jsonb_array_elements_text(coalesce(pa->'mapped','[]'::jsonb)) loop
        insert into mapped_values(parameter_id, value) values(pid, mv) on conflict(parameter_id, value) do update set is_active=true;
      end loop;
      ord := ord + 1;
    end loop;
  end loop;

  -- derive event New/Updated the same way the app reads it
  update events e set change_status = case
    when lower(coalesce(e.type,'')) like '%new event%'     then 'NEW'
    when lower(coalesce(e.type,'')) like '%add parameter%' then 'UPDATED'
    when exists(select 1 from event_parameters ep where ep.event_id=e.id and ep.change_status is not null) then 'UPDATED'
    else null end;

  -- rebuild the change feed for the current release
  delete from change_log where spec_version='1.2';
  insert into change_log(spec_version, entity, entity_key, kind)
    select '1.2','event', name, case when change_status='NEW' then 'added' else 'changed' end
    from events where change_status is not null;
  insert into change_log(spec_version, entity, entity_key, kind)
    select '1.2','parameter', ev.name || '::' || p.name, case when ep.change_status='NEW' then 'added' else 'changed' end
    from event_parameters ep
    join events ev on ev.id = ep.event_id
    join parameters p on p.id = ep.parameter_id
    where ep.change_status is not null;
end $$;
